//! The pages of the galaxy's kinds: galaxies (with an example generated by the `galaxy` crate), bands, cluster
//! types, trails, signal sources and lore fragments.

use super::*;
use data::{Band, ClusterType, Galaxy, LoreFragment, Reward, SignalSource, SourceForm, Trail};

/// The seed of the galaxy page's example.
pub(crate) const EXAMPLE_SEED: u64 = 1;

/// The badge of a stand-in entry (tag `stub`): only the rim is real so far.
pub(crate) fn stub(tags: &[String]) -> &'static str {
    if tags.iter().any(|t| t == "stub") {
        " <span class=\"badge stub\" title=\"A stand-in until its band has its own race and guardian\">Stub</span>"
    } else {
        ""
    }
}

pub(crate) fn reward_word(r: Reward) -> &'static str {
    match r {
        Reward::Gate => "A band gate",
        Reward::Cache => "A precursor cache",
        Reward::Lore => "A lore fragment",
        Reward::Salvage => "Rich salvage",
    }
}

pub(crate) fn form_word(f: SourceForm) -> &'static str {
    match f {
        SourceForm::Log => "A log in a wreck",
        SourceForm::Beacon => "A beacon",
    }
}

/// A cluster type's radius: "2000–2600 m".
pub(crate) fn radius(t: &ClusterType) -> String {
    format!("{}–{}", format_number(t.radius.0, 0), metres(t.radius.1))
}

/// A signal's first line as the map shows it: "SIGNAL · A GATE".
fn signal_line(hint: &str) -> String {
    format!("SIGNAL · {}", hint.to_uppercase())
}

impl Wiki<'_> {
    /// `a`–`b` in S.
    pub(crate) fn s_range(&self, (a, b): (f32, f32)) -> String {
        format!("{}–{}", format_number(a, 2), self.value("galaxy_distance", b))
    }

    /// A band's cluster types as `type (share)`, one per line.
    fn band_types(&self, root: &str, b: &Band) -> String {
        let total: u32 = b.clusters.iter().map(|w| w.weight).sum::<u32>().max(1);
        let v: Vec<String> = b
            .clusters
            .iter()
            .map(|w| format!("{} ({}%)", self.a(root, Kind::ClusterType, &w.id), format_number(100.0 * w.weight as f32 / total as f32, 0)))
            .collect();
        v.join("<br>")
    }

    pub(crate) fn galaxy_page(&self, g: &Galaxy) -> String {
        let root = UP;
        let c = self.c;
        let facts = vec![
            ("Bands".to_string(), g.bands.len().to_string()),
            ("Spacing".into(), format!("<span title=\"No two clusters closer\">{}</span>", self.value("galaxy_distance", g.spacing))),
            ("Jump range at the start".into(), self.value("jump_range", g.jump_range)),
            ("Home".into(), format!("{} or more clusters within the jump range", g.home_neighbours)),
            ("Warp time".into(), format!("{} s + {} s per S", format_number(g.warp.0, 1), format_number(g.warp.1, 1))),
            ("Fresh signal area".into(), format!("{} across", self.s_range(g.signal_area.across))),
            ("Trail step".into(), self.s_range(g.trail_step)),
            ("Name parts".into(), format!("{} starts, {} ends", g.names.starts.len(), g.names.ends.len())),
        ];
        let mut bands = String::from(
            "<table class=\"list\">\n<tr><th>Band</th><th class=\"num\">Edge</th><th>Clusters</th><th>Gates</th></tr>\n",
        );
        for b in g.bands.iter().filter_map(|b| c.bands.get(b)) {
            let gates = b
                .gates
                .as_ref()
                .map_or("—".into(), |x| format!("{}&nbsp;× {}", x.count, self.a(root, Kind::Trail, &x.trail)));
            writeln!(
                bands,
                "<tr><td class=\"name\">{}{}</td><td class=\"num\">{}</td><td>{}</td><td>{gates}</td></tr>",
                self.a(root, Kind::Band, &b.id),
                stub(&b.tags),
                self.value("galaxy_distance", b.edge),
                self.band_types(root, b)
            )
            .unwrap();
        }
        bands.push_str("</table>\n<p class=\"note\">A band reaches from its edge in to the next band's edge (the core's to the centre).</p>\n");
        let example = match ::galaxy::generate(c, &g.id, EXAMPLE_SEED) {
            Ok(s) => {
                let counts: Vec<String> =
                    g.bands.iter().map(|b| format!("{} {}", esc(b), s.band(b).count())).collect();
                format!(
                    "<figure class=\"galaxy-map\">{}</figure>\n<p class=\"note\">Seed {EXAMPLE_SEED}: {} clusters ({}), {} trails. Home is the teal diamond inside its jump range, gates are gold; each trail runs from its first source to its reward (gold: a gate, violet: a cache, teal: lore, coral: salvage), with its signals' fresh areas dotted. Every game generates its own galaxy from its seed, and its save keeps it.</p>\n",
                    super::super::map::svg(c, &s, &self.style, 48.0, false),
                    s.clusters.len(),
                    counts.join(", "),
                    s.trails.len()
                )
            }
            Err(e) => {
                self.warn(format!("galaxy `{}`: the example does not generate: {e}", g.id));
                none()
            }
        };
        self.entry(
            g,
            EntryParts {
                facts,
                sections: vec![("Bands".to_string(), bands), ("An example".into(), example)],
                ..Default::default()
            },
        )
    }

    pub(crate) fn band_page(&self, b: &Band) -> String {
        let root = UP;
        let c = self.c;
        let mut facts = Vec::new();
        let galaxies: Vec<&Galaxy> = c.galaxies.iter().filter(|g| g.bands.contains(&b.id)).collect();
        if let Some(l) = self.links(root, galaxies.iter().map(|g| (Kind::Galaxy, g.id.clone()))) {
            facts.push(("Galaxy".to_string(), l));
        }
        facts.push(("Outer edge".into(), self.value("galaxy_distance", b.edge)));
        let inner = galaxies
            .first()
            .and_then(|g| g.bands.iter().position(|x| *x == b.id).and_then(|k| g.bands.get(k + 1)))
            .and_then(|x| c.bands.get(x))
            .map_or("the centre".into(), |x| self.value("galaxy_distance", x.edge));
        facts.push(("Inner edge".into(), inner));
        if let Some(gates) = &b.gates {
            facts.push(("Gates".into(), gates.count.to_string()));
        }
        let mut types = String::from("<table class=\"list\">\n<tr><th></th><th></th><th class=\"num\">Share</th><th class=\"num\">Radius</th></tr>\n");
        let total: u32 = b.clusters.iter().map(|w| w.weight).sum::<u32>().max(1);
        for w in &b.clusters {
            let Some(t) = c.cluster_types.get(&w.id) else { continue };
            writeln!(
                types,
                "<tr><td class=\"name\">{}</td><td>{}</td><td class=\"num\">{}%</td><td class=\"num\">{}</td></tr>",
                self.a(root, Kind::ClusterType, &t.id),
                self.text(root, &t.summary),
                format_number(100.0 * w.weight as f32 / total as f32, 0),
                radius(t)
            )
            .unwrap();
        }
        types.push_str("</table>\n");
        let mut trails = Vec::new();
        if let Some(g) = &b.gates {
            trails.push((g.trail.as_str(), format!("{} (one per gate)", g.count)));
        }
        for t in &b.trails {
            trails.push((t.trail.as_str(), t.count.to_string()));
        }
        for l in c.lore.iter().filter(|l| l.band == b.id) {
            trails.push((l.trail.as_str(), format!("1, to {}", self.a(root, Kind::Lore, &l.id))));
        }
        let rows: String = trails
            .iter()
            .filter_map(|(id, n)| {
                let t = c.trails.get(id)?;
                Some(format!(
                    "<tr><td class=\"name\">{}</td><td>{}</td><td class=\"num\">{n}</td></tr>\n",
                    self.a(root, Kind::Trail, id),
                    reward_word(t.reward)
                ))
            })
            .collect();
        let trails = if rows.is_empty() { none() } else { format!("<table class=\"list\">\n{rows}</table>\n") };
        self.entry(
            b,
            EntryParts {
                facts,
                sections: vec![("Cluster types".to_string(), types), ("Trails".into(), trails)],
                ..Default::default()
            },
        )
    }

    pub(crate) fn cluster_type_page(&self, t: &ClusterType) -> String {
        let root = UP;
        let c = self.c;
        let words: Vec<String> = t.words.iter().map(|w| format!("… {}", esc(w))).collect();
        let facts = vec![
            ("Radius".to_string(), radius(t)),
            ("Site spacing".into(), format!("{}–{}", format_number(t.spacing.0, 0), metres(t.spacing.1))),
            ("Names".into(), words.join(", ")),
        ];
        let mut sites = String::from(
            "<p>Each cluster of this type rolls its radius and how many of each site it holds from its own seed, when the fleet first warps in; the places of trails the galaxy put there come on top.</p>\n<table class=\"list\">\n<tr><th>Encounter</th><th>Ships</th><th>Wrecks</th><th class=\"num\">Sites</th></tr>\n",
        );
        for s in &t.sites {
            let (ships, wrecks) = c
                .encounters
                .get(&s.encounter)
                .map(|e| (self.encounter_ships(root, e), self.encounter_wrecks(root, e)))
                .unwrap_or_default();
            writeln!(
                sites,
                "<tr><td class=\"name\">{}</td><td>{ships}</td><td>{wrecks}</td><td class=\"num\">×{}</td></tr>",
                self.a(root, Kind::Encounter, &s.encounter),
                count_range(s.count)
            )
            .unwrap();
        }
        sites.push_str("</table>\n");
        let bands: Vec<String> = c
            .bands
            .iter()
            .filter(|b| b.clusters.iter().any(|w| w.id == t.id))
            .map(|b| self.a(root, Kind::Band, &b.id))
            .collect();
        self.entry(
            t,
            EntryParts {
                facts,
                sections: vec![("Sites".to_string(), sites), ("In bands".into(), list_or_none(&bands))],
                ..Default::default()
            },
        )
    }

    pub(crate) fn trail_page(&self, t: &Trail) -> String {
        let root = UP;
        let c = self.c;
        let facts = vec![
            ("Leads to".to_string(), reward_word(t.reward).into()),
            ("Signals".into(), count_range(t.length)),
            ("At its end".into(), self.a(root, Kind::Encounter, &t.target)),
            ("On the map".into(), format!("<span class=\"sig\">{}</span>", self.text(root, &signal_line(&t.hint)))),
        ];
        let mut sources = String::from("<p>Each of its signals comes from one of these, equally likely; the first lies in an ordinary cluster of the band, each later one where the signal before it led.</p>\n<table class=\"list\">\n");
        for id in &t.sources {
            let Some(s) = c.signal_sources.get(id) else { continue };
            writeln!(
                sources,
                "<tr><td class=\"name\">{}</td><td>{}</td><td>“{}”</td></tr>",
                self.a(root, Kind::SignalSource, id),
                form_word(s.form),
                self.text(root, &s.line)
            )
            .unwrap();
        }
        sources.push_str("</table>\n");
        let mut placed = Vec::new();
        for b in &c.bands {
            if let Some(g) = b.gates.as_ref().filter(|g| g.trail == t.id) {
                placed.push(format!("{}: one to each of its {} gates", self.a(root, Kind::Band, &b.id), g.count));
            }
            for x in b.trails.iter().filter(|x| x.trail == t.id) {
                placed.push(format!("{}: ×{}", self.a(root, Kind::Band, &b.id), x.count));
            }
        }
        for l in c.lore.iter().filter(|l| l.trail == t.id) {
            placed.push(format!("{}, to {}", self.a(root, Kind::Band, &l.band), self.a(root, Kind::Lore, &l.id)));
        }
        self.entry(
            t,
            EntryParts {
                badges: stub(&t.tags).into(),
                facts,
                sections: vec![("Signal sources".to_string(), sources), ("Placed in".into(), list_or_none(&placed))],
                ..Default::default()
            },
        )
    }

    pub(crate) fn signal_source_page(&self, s: &SignalSource) -> String {
        let root = UP;
        let how = match s.form {
            SourceForm::Log => "a data core in a wreck: salvaged, brought home and decoded there, free",
            SourceForm::Beacon => "scanned in the cluster: a signal at once",
        };
        let facts = vec![
            ("Form".to_string(), form_word(s.form).into()),
            ("Found".into(), how.into()),
            ("On the map".into(), format!("“{}”", self.text(root, &s.line))),
            ("At its place".into(), s.site.as_ref().map_or("the beacon alone".into(), |e| self.a(root, Kind::Encounter, e))),
        ];
        let trails: Vec<String> =
            self.c.trails.iter().filter(|t| t.sources.contains(&s.id)).map(|t| self.a(root, Kind::Trail, &t.id)).collect();
        self.entry(
            s,
            EntryParts {
                facts,
                sections: vec![("Used by trails".to_string(), list_or_none(&trails))],
                ..Default::default()
            },
        )
    }

    pub(crate) fn lore_page(&self, l: &LoreFragment) -> String {
        let root = UP;
        let facts = vec![
            ("Band".to_string(), self.a(root, Kind::Band, &l.band)),
            ("Trail".into(), self.a(root, Kind::Trail, &l.trail)),
        ];
        let text = format!(
            "<blockquote><p>{}</p></blockquote>\n<p class=\"note\">Found at the end of its trail and kept in the memory log.</p>\n",
            self.text(root, &l.text)
        );
        self.entry(
            l,
            EntryParts {
                facts,
                sections: vec![("The fragment".to_string(), text)],
                ..Default::default()
            },
        )
    }
}
